"""E2e tests for category: static_files."""

import os
import urllib.request

import pytest


def test_static_file_server_returns_text_file() -> None:
    """Tests serving a plain text file with Cache-Control headers."""
    base = os.environ.get("SUT_URL", "http://127.0.0.1:8000")
    url = f"{base}/fixtures/static_file_server_returns_text_file/public/hello.txt"
    _headers = {}
    _req = urllib.request.Request(url, headers=_headers, method="GET")  # noqa: S310

    class _NoRedirect(urllib.request.HTTPRedirectHandler):
        def redirect_request(self, *args, **kwargs):  # noqa: ANN002, ANN003, ANN202, ARG002
            return None

    _opener = urllib.request.build_opener(_NoRedirect())
    try:
        response = _opener.open(_req)
        status_code = response.status
        resp_body = response.read()
        resp_headers = dict(response.headers)
    except urllib.error.HTTPError as _exc:
        status_code = _exc.code
        resp_body = _exc.read()
        resp_headers = dict(_exc.headers)
    assert status_code == 200
    assert resp_body.decode() == "Hello from static storage"
    assert resp_headers["cache-control"] == "public, max-age=60"
    assert resp_headers["content-type"] == "text/plain"


def test_static_server_returns_index_html_for_directory() -> None:
    """When index files are enabled the server should serve index.html when the directory root is requested."""
    base = os.environ.get("SUT_URL", "http://127.0.0.1:8000")
    url = f"{base}/fixtures/static_server_returns_index_html_for_directory/app/"
    _headers = {}
    _req = urllib.request.Request(url, headers=_headers, method="GET")  # noqa: S310

    class _NoRedirect(urllib.request.HTTPRedirectHandler):
        def redirect_request(self, *args, **kwargs):  # noqa: ANN002, ANN003, ANN202, ARG002
            return None

    _opener = urllib.request.build_opener(_NoRedirect())
    try:
        response = _opener.open(_req)
        status_code = response.status
        resp_body = response.read()
        resp_headers = dict(response.headers)
    except urllib.error.HTTPError as _exc:
        status_code = _exc.code
        resp_body = _exc.read()
